-- AUTO-GENERATED: do not edit by hand.
-- Registers every UI string used by KullThranUI modules that was missing
-- from the locale tables. Values are the English string as a placeholder;
-- translators can replace them per language.
local _, ns = ...

local locales = ns and ns.Locales
if type(locales) ~= "table" then
    return
end

local function apply(locale, entries)
    if type(locale) ~= "table" then return end
    for key, value in pairs(entries) do
        if locale[key] == nil then
            locale[key] = value
        end
    end
end

